import * as React from "react"
import { Link } from "gatsby"
import { navbar, container, brand, brandMark, brandName, navLinks, navLinkItem, navLinkActive, labelLong, labelShort } from "./styles/navbar.module.css"

// `short` is shown instead of `label` on narrow screens; `partiallyActive` keeps sub-pages highlighted
const NAV_ITEMS = [
    { to: "/", label: "Home" },
    // { to: "/portfolio", label: "Portfolio" },
    // { to: "/publication", label: "Publication" },
    { to: "/tech_demo", label: "Technical demo", short: "Tech demo" },
    { to: "/ongoing_render_debug", label: "Cel-shading testbed", short: "Cel-shading" },
    { to: "/blog", label: "Blog", partiallyActive: true },
]

const Navbar = (prop) => {
    return (
        <nav className={navbar} aria-label="Main">
            <div className={container}>
                <Link to="/" className={brand} aria-label="Jian-Kai Zhu, home">
                    <span className={brandMark} aria-hidden="true">JK</span>
                    <span className={brandName}>Jian-Kai Zhu</span>
                </Link>

                <ul className={navLinks}>
                    {NAV_ITEMS.map((item) => (
                        <li key={item.to}>
                            <Link
                                to={item.to}
                                className={navLinkItem}
                                activeClassName={navLinkActive}
                                partiallyActive={item.partiallyActive}
                            >
                                {item.short ? (
                                    <>
                                        <span className={labelLong}>{item.label}</span>
                                        <span className={labelShort}>{item.short}</span>
                                    </>
                                ) : (
                                    item.label
                                )}
                            </Link>
                        </li>
                    ))}
                </ul>
            </div>
        </nav>
    )
}

// export default IndexPage
export default Navbar
